from AlgorithmImports import *


class StrategySystemAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol

        self.spy_sma = self.SMA(self.spy, 100, Resolution.Daily)
        self.aapl_rsi = self.RSI(
            self.aapl, 14, MovingAverageType.Wilders, Resolution.Daily
        )

        self.SetWarmUp(100, Resolution.Daily)

        self.lots = {
            "A": 0,
            "B": 0
        }

        self.pending_orders = {}

        self.spy_previous_close = None
        self.spy_previous_sma = None

        self.aapl_previous_close = None
        self.aapl_red_count = 0

    def OnData(self, data):
        symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        available = {
            symbol: symbol in data.Bars
            for symbol in symbols
        }

        if available[self.spy]:
            spy_close = data.Bars[self.spy].Close

            if self.spy_sma.IsReady:
                self.spy_previous_close = getattr(
                    self, "_spy_current_close", self.spy_previous_close
                )
                self.spy_previous_sma = getattr(
                    self, "_spy_current_sma", self.spy_previous_sma
                )
                self._spy_current_close = spy_close
                self._spy_current_sma = self.spy_sma.Current.Value

        if available[self.aapl]:
            aapl_close = data.Bars[self.aapl].Close

            if self.aapl_previous_close is not None:
                if aapl_close < self.aapl_previous_close:
                    self.aapl_red_count += 1
                else:
                    self.aapl_red_count = 0

            self.aapl_previous_close = aapl_close

        if self.IsWarmingUp:
            return

        if not all(available.values()):
            return

        spy_close = data.Bars[self.spy].Close
        aapl_close = data.Bars[self.aapl].Close

        spy_today_sma = self.spy_sma.Current.Value
        aapl_today_rsi = self.aapl_rsi.Current.Value

        spy_crosses_below = (
            self.spy_previous_close is not None
            and self.spy_previous_sma is not None
            and self.spy_previous_close <= self.spy_previous_sma
            and spy_close > self.spy_previous_sma
        )

        spy_crosses_above = (
            self.spy_previous_close is not None
            and self.spy_previous_sma is not None
            and self.spy_previous_close >= self.spy_previous_sma
            and spy_close < self.spy_previous_sma
        )

        if (
            self.lots["A"] > 0
            and not self._has_pending_order("A")
            and spy_crosses_above
        ):
            self._submit_sell("A", self.lots["A"], "Strategy A sell")

        if (
            self.lots["B"] > 0
            and not self._has_pending_order("B")
            and self.aapl_rsi.IsReady
            and aapl_today_rsi > 60
        ):
            self._submit_sell("B", self.lots["B"], "Strategy B sell")

        if (
            self.lots["A"] == 0
            and not self._has_pending_order("A")
            and spy_crosses_below
            and self.spy_sma.IsReady
        ):
            quantity = int(
                (self.Portfolio.TotalPortfolioValue * 0.40) / spy_close
            )
            if quantity > 0:
                self._submit_buy("A", quantity, "Strategy A buy")

        if (
            self.lots["B"] == 0
            and not self._has_pending_order("B")
            and self.aapl_red_count >= 3
            and self.Portfolio.Cash >= 20000
        ):
            quantity = int(20000 / aapl_close)
            if quantity > 0:
                self._submit_buy("B", quantity, "Strategy B buy")

        self.spy_previous_close = spy_close
        self.spy_previous_sma = spy_today_sma

    def _has_pending_order(self, strategy):
        return any(
            order_strategy == strategy
            for order_strategy, _ in self.pending_orders.values()
        )

    def _submit_buy(self, strategy, quantity, tag):
        symbol = self.spy if strategy == "A" else self.aapl
        ticket = self.MarketOrder(symbol, quantity, tag=tag)
        self.pending_orders[ticket.OrderId] = (strategy, "buy")

    def _submit_sell(self, strategy, quantity, tag):
        symbol = self.spy if strategy == "A" else self.aapl
        ticket = self.MarketOrder(symbol, -quantity, tag=tag)
        self.pending_orders[ticket.OrderId] = (strategy, "sell")

    def OnOrderEvent(self, order_event):
        order_id = order_event.OrderId

        if order_id not in self.pending_orders:
            return

        strategy, order_type = self.pending_orders[order_id]

        if order_event.Status in (
            OrderStatus.Filled,
            OrderStatus.PartiallyFilled
        ):
            self.lots[strategy] += order_event.FillQuantity
            self.lots[strategy] = max(0, self.lots[strategy])

        if order_event.Status in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        ):
            del self.pending_orders[order_id]
